contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint deposit, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (deposit)); require(deposit <= 1000000000000000000000000000000);
        require(deposit > 0 && amount > 0 && amount <= deposit);
        require(address(this).balance >= deposit);
        // use this contract as the log: its fallback accepts any call
        c.SetLogFile(address(this)); if (__ESBMC_reverted()) return;
        c.SetMinSum(0); if (__ESBMC_reverted()) return;
        c.Deposit{value: deposit}(); if (__ESBMC_reverted()) return;
        uint balBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint ethBefore = address(c).balance;
        c.Collect(amount); if (__ESBMC_reverted()) return;
        assert(c.balances(address(this)) == balBefore - amount && address(c).balance == ethBefore - amount);
    }
    receive() external payable {}
    fallback() external payable {}
}

