// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function _run(uint256 deposit, uint256 amount) internal {
        deposit = bound(deposit, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(deposit > 0 && amount > 0 && amount <= deposit);
        vm.assume(address(this).balance >= deposit);
        try c.SetLogFile(address(this)) {} catch { return; }
        try c.SetMinSum(0) {} catch { return; }
        try c.Deposit{value: deposit}() {} catch { return; }
        uint256 balBefore;
        try c.balances(address(this)) returns (uint256 __r) { balBefore = __r; } catch { return; }
        uint ethBefore = address(c).balance;
        try c.Collect(amount) {} catch { return; }
        assertTrue(c.balances(address(this)) == balBefore - amount && address(c).balance == ethBefore - amount);
    }

    function testFuzz_run(uint256 deposit, uint256 amount) public {
        _run(deposit, amount);
    }

    receive() external payable {}

    fallback() external payable {}
}
